const privacyContactLinks = privacyContact ? [{ href: `mailto:${privacyContact}`, label: `Написати щодо персональних даних: ${privacyContact}` }] : []

function merchantDetails(): string[] {
  return [
    legalMerchant.name && `Продавець послуг: ${legalMerchant.name}.`,
    legalMerchant.taxId && `РНОКПП (ІПН): ${legalMerchant.taxId}.`,
    legalMerchant.registrationAddress && `Адреса реєстрації: ${legalMerchant.registrationAddress}.`,
    legalMerchant.actualAddress && `Фактична адреса: ${legalMerchant.actualAddress}.`,
    legalMerchant.phone && `Телефон: ${legalMerchant.phone}.`,
    legalMerchant.email && `Електронна пошта: ${legalMerchant.email}.`,
  ].filter((value): value is string => Boolean(value))
}

function supportInstruction(): string {
  return legalMerchant.email
    ? `Надішліть звернення на ${legalMerchant.email}. Телефон підтримки та повні реквізити наведені на сторінці «Контакти та реквізити».`
    : 'Звертайтеся за контактами підтримки, опублікованими на сторінці «Контакти та реквізити».'
}

